declare(strict_types=1);use ImAuthenticator\Security;use ImAuthenticator\Web;$services=require dirname(__DIR__).'/src/bootstrap.php';extract($services,EXTR_SKIP);$admin=$auth->requireAdmin();$msg='';if(strtoupper($_SERVER['REQUEST_METHOD']??'GET')==='POST'){Security::requireCsrf($_POST['_csrf']??null);try{$r=$impersonation->start((int)$admin['id'],(int)$_POST['target_user_id'],(string)$_POST['reason']);$_SESSION['impersonation_actor_id']=(int)$admin['id'];$_SESSION['impersonation_session_id']=(int)$r['id'];$_SESSION['user_id']=(int)$r['target_user_id'];$_SESSION['auth_level']=1;Web::redirect('/dashboard');}catch(Throwable $e){$msg='<div class="alert danger">'.Web::e($e->getMessage()).'</div>';}}
$options='';foreach($db->all("SELECT id,name,email FROM users WHERE enabled=1 AND lifecycle_status='active' AND is_admin=0 AND break_glass=0 ORDER BY name") as $u)$options.='<option value="'.(int)$u['id'].'">'.Web::e($u['name'].' — '.$u['email']).'</option>';Web::page('Impersonation','<div class="page-head"><div><h1>User impersonation</h1><p>Pełny audyt, obowiązkowy powód i zakaz wejścia jako konto uprzywilejowane.</p></div></div>'.$msg.'<form class="card" method="post"><input type="hidden" name="_csrf" value="'.Web::e(Security::csrfToken()).'"><label>Użytkownik<select name="target_user_id">'.$options.'</select></label><label>Powód<textarea name="reason" required></textarea></label><button class="primary">Rozpocznij impersonację</button></form>',$admin);
